import {COW} from './cow-config.js';import {cowCapacity,createCow} from './cow-state.js';import {cowAccessibleSupply} from './cow-recovery.js';
/** @param {import('./engine.js').State} state */
export function cowPurchaseReason(state){const g=state.cow;if(!g?.visited)return 'cowNotVisited';if(g.stats.purchasedCows||g.cows.length>=3)return 'cowNoMoreCows';const cap=cowCapacity(g),supply=cowAccessibleSupply(state);if(cap.cows<3)return 'cowExpandFirst';if(g.cows.length!==2)return 'cowNeedCompanions';if(cap.feedG<3*COW.feedDayG)return 'cowFeedCapacity';if(cap.waterMl<3*COW.hotWaterDayMl)return 'cowWaterCapacity';if(supply.feedG<3*COW.feedDayG)return 'cowNeedFeedDay';if(supply.waterMl<3*COW.hotWaterDayMl)return 'cowNeedWaterDay';return state.coins<COW.cowPrice?'noCoins':'';}
/** One adult, already-calved/lactating cow with no free milk or supplies. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./engine.js').DomainEvent[]} events @param {import('./cow-runtime.js').CowTransaction} transact */
export function applyCowPurchase(state,command,events,transact){const reason=cowPurchaseReason(state);if(reason)return reason;const g=state.cow;if(!g)return 'cowNotVisited';const cap=cowCapacity(g),supply=cowAccessibleSupply(state);transact(state,'cow_purchase',-COW.cowPrice,command.id+':cow.purchase.1');g.purchaseProof={tick:state.tick,feedCapacityG:cap.feedG,waterCapacityMl:cap.waterMl,availableFeedG:supply.feedG,availableWaterMl:supply.waterMl};g.cows.push(createCow('cow.bought.1',state.tick));g.stats.purchasedCows++;events.push({type:'cowPurchased'});return '';}
